<?php
require_once __DIR__ . '/_friend_helpers.php';
try { if($_SERVER['REQUEST_METHOD']!=='GET'){ApiResponse::send(false,[],'Method not allowed.',[],405);exit;} $c=friends_connection(); if(!SessionHelper::isAuthenticated()){ApiResponse::unauthorized();exit;} $uid=(int)($_GET['user_id']??0); $page=max(1,(int)($_GET['page']??1)); $limit=min(50,max(1,(int)($_GET['limit']??20))); $offset=($page-1)*$limit; if($uid<=0||!friends_can_view_profile($c,$uid)){ApiResponse::forbidden('Not allowed to view friends.');exit;} $cnt=$c->prepare("SELECT COUNT(*) total FROM friendships WHERE user_id=:uid AND status='accepted'"); $cnt->execute(['uid'=>$uid]); $total=(int)$cnt->fetch(PDO::FETCH_ASSOC)['total']; $s=$c->prepare("SELECT u.id,u.username,u.full_name,u.profile_photo,u.is_memorial FROM friendships f JOIN users u ON u.id=f.friend_id WHERE f.user_id=:uid AND f.status='accepted' AND u.status='active' ORDER BY u.full_name ASC LIMIT :limit OFFSET :offset"); $s->bindValue(':uid',$uid,PDO::PARAM_INT);$s->bindValue(':limit',$limit,PDO::PARAM_INT);$s->bindValue(':offset',$offset,PDO::PARAM_INT);$s->execute(); $friends=array_map('friends_safe_user',$s->fetchAll(PDO::FETCH_ASSOC)); ApiResponse::success(['friends'=>$friends,'pagination'=>['current_page'=>$page,'per_page'=>$limit,'total_items'=>$total,'total_pages'=>(int)ceil($total/$limit)]],'Friends loaded.'); } catch(Throwable $e){Logger::error('Friend list failed',['error'=>$e->getMessage()]);ApiResponse::serverError('Unable to load friends.');}
?>
